import snapshot from "./ecosystem.generated.json";

/**
 * Ecosystem data generated by `scripts/generate-ecosystem.mjs` from
 * `packages/ * /package.json` and `veap-registry.json`. Nothing here is
 * hand-maintained, and the `ecosystem:check` script fails when the snapshot is
 * stale.
 *
 * The homepage prints the totals; the ownership map additionally documents the
 * reference application layout described in
 * `docs/developer-docs/getting-started/project-structure.md`, and the generator
 * asserts that every path it lists still exists in this repository.
 */

export type PackageKind = "service" | "ui" | "tooling" | "trait";
export type RegistryKind = "plugin" | "trait";

export interface EcosystemProvider {
  symbol: string;
  from: string;
}

export interface EcosystemPackage {
  name: string;
  version: string;
  kind: PackageKind;
  license: string | null;
  repository: string | null;
  dir: string;
  docs: string;
  blurb: string;
  providers: EcosystemProvider[];
  migrations: boolean;
  deps: string[];
  peers: string[];
  exports: string[];
  exportCount: number;
  private: boolean;
  layer: number;
}

export interface RegistryEntry {
  id: string;
  slug: string;
  name: string;
  package: string;
  version: string;
  category: string;
  status: string;
  kind: RegistryKind;
  featured: boolean;
  isNew: boolean;
  install: string | null;
  hasMigrations: boolean;
  repository: string | null;
  docs: string;
  dependencies: string[];
}

export interface EcosystemDemo {
  dir: string;
  package: string;
  veapDeps: string[];
}

/**
 * Ownership map: which package - or you - writes which file of a real
 * application. Generated from curated rules that are asserted to exist in the
 * reference apps, so the tree cannot point at a file layout that moved.
 */
export type OwnershipEditable = "you" | "generated" | "package";

/** A file or directory in the ownership tree (both carry `children`). */
export interface OwnershipNode {
  name: string;
  path: string;
  dir: boolean;
  children: OwnershipNode[];
  /** Files only: the owning package name, or a synthetic owner key. */
  owner?: string;
  ownerLabel?: string;
  ownerKind?: PackageKind | "app";
  role?: string;
  editable?: OwnershipEditable;
  docs?: string;
  /** Where the path was observed: an app folder, the scaffold or this repo. */
  source?: string;
}

export interface EjectFile {
  path: string;
  before: string[];
  after: string[];
  note: string;
}

export interface EjectGuide {
  target: string;
  label: string;
  version: string;
  dir: string;
  repository: string;
  install: string | null;
  title: string;
  steps: string[];
  files: EjectFile[];
  caveat: string;
}

export interface OwnershipMap {
  reference: string;
  files: number;
  owners: string[];
  nodes: OwnershipNode[];
  eject: EjectGuide | null;
}

export interface EcosystemSnapshot {
  generatedFrom: string;
  totals: {
    packages: number;
    services: number;
    ui: number;
    tooling: number;
    traits: number;
    exportSubpaths: number;
    registryEntries: number;
    plugins: number;
  };
  layers: Array<{ depth: number; packages: string[] }>;
  packages: EcosystemPackage[];
  registry: RegistryEntry[];
  demos: EcosystemDemo[];
  ownership: OwnershipMap;
}

export const ecosystem = snapshot as unknown as EcosystemSnapshot;

export const ecosystemPackages = ecosystem.packages;
export const registryEntries = ecosystem.registry;
export const ecosystemTotals = ecosystem.totals;
export const ecosystemDemos = ecosystem.demos;
export const ecosystemOwnership = ecosystem.ownership;

export function packageByName(name: string): EcosystemPackage | undefined {
  return ecosystemPackages.find((pkg) => pkg.name === name);
}
